 * Splits the input into an array of Unicode code points and computes the
 * 1-based line and column of every one of them, following the rules:
 *   - a line feed moves to the next line and resets the column to 1
 *   - a tab moves the column forward to the next multiple of 4, plus 1
 *   - every other code point moves the column forward by 1
 */
export function computePositions(input) {
  const chars = Array.from(input)
  const lines = new Array(chars.length)
  const cols = new Array(chars.length)
  let line = 1
  let col = 1
  for (let i = 0; i < chars.length; i++) {
    lines[i] = line
    cols[i] = col
    const ch = chars[i]
    if (ch === '\n') {
      line += 1
      col = 1
    } else if (ch === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col += 1
    }
  }
  return { chars, lines, cols }
}
"}

